import{_ as r}from"./chunks/telegram.s4hL_0v3.js";import{_ as e,o as t,c as n,a2 as o}from"./chunks/framework.DSc8fo6x.js";const p=JSON.parse('{"title":"Telegram: gündəlik hesabat və backup","description":"","frontmatter":{},"headers":[],"relativePath":"telegram.md","filePath":"telegram.md"}'),l={name:"telegram.md"};function i(s,a,d,m,g,b){return t(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="telegram-gundəlik-hesabat-və-backup" tabindex="-1">Telegram: gündəlik hesabat və backup <a class="header-anchor" href="#telegram-gundəlik-hesabat-və-backup" aria-label="Permalink to &quot;Telegram: gündəlik hesabat və backup&quot;">​</a></h1><p>Hər axşam sahibin telefonuna qısa <strong>hesabat</strong> (satış, dövriyyə, nağd və kart, ləğvlər — kim etdi, bitmək üzrə olan mallar) və <strong>şifrəli backup</strong> gəlir. Kompüter oğurlansa və ya xarab olsa da, Telegram-dakı nüsxə qalır.</p><p><strong>Mesaj gəlmirsə — bu özü xəbərdarlıqdır:</strong> nəsə yolunda deyil.</p><h2 id="qosmaq-bir-dəfə-internet-lazımdır" tabindex="-1">Qoşmaq (bir dəfə, internet lazımdır) <a class="header-anchor" href="#qosmaq-bir-dəfə-internet-lazımdır" aria-label="Permalink to &quot;Qoşmaq (bir dəfə, internet lazımdır)&quot;">​</a></h2><ol><li>Telefonda Telegram-da <strong>@BotFather</strong>-ı tapın → <code>/newbot</code> → bota ad verin (məs. &quot;Mağaza Kassa&quot;) və istifadəçi adı (sonu <code>bot</code> ilə bitməlidir).</li><li>BotFather uzun bir <strong>token</strong> verir (<code>123456789:AA…</code>). Onu kopyalayın.</li><li>Kassa → <strong>Ayarlar → Telegram</strong> → <strong>Bot tokeni</strong> sahəsinə yapışdırın.</li><li>Telegram-da öz botunuzu tapın və ona <strong><code>/start</code></strong> yazın. <ul><li><strong>Qrupa göndərmək üçün:</strong> botu qrupa əlavə edin və qrupda <strong><code>/start@botun_adı</code></strong> yazın (məs. <code>/start@magaza_kassa_bot</code>). Adi mesaj kifayət etmir — Telegram qrupdakı adi mesajları bota göstərmir.</li></ul></li><li>Kassa-da <strong>Çatı tap</strong>. Bir neçə çat tapılsa (şəxsi və qrup) — siyahıdan seçin. Seçim <strong>özü yadda saxlanılır</strong>.</li><li>Hesabat vaxtını seçin (məs. 21:00) → <strong>Sınaq mesajı</strong>. Telefona mesaj gəlməlidir.</li></ol><p><img src="'+r+'" alt="Telegram"></p><h2 id="sonra" tabindex="-1">Sonra <a class="header-anchor" href="#sonra" aria-label="Permalink to &quot;Sonra&quot;">​</a></h2><ul><li>Hesabat hər gün seçilmiş vaxtda. Proqram o vaxtdan əvvəl bağlanıbsa — ertəsi gün &quot;gecikmiş hesabat&quot;.</li><li>Backup gündə bir dəfə. Böyük bazada fayl hissələrə bölünür (<code>.001</code>, <code>.002</code>…).</li><li>İnternet yoxdursa, 15 dəqiqədən bir yenidən cəhd. Son göndərişin vaxtı və nəticəsi Ayarlarda görünür.</li><li>Saxlanmış token ekranda göstərilmir (sahə boşdur, &quot;Saxlanılıb&quot; yazılır). Kimsə tokeni bilsə — BotFather-da <code>/revoke</code>.</li></ul><div class="warning custom-block"><p class="custom-block-title">Sarı xəbərdarlıq &quot;Telegram-a backup getmir&quot;</p><p>2 gündən çoxdur heç nə gedə bilmir. Səbəb xəbərdarlıqda yazılır. Yoxlayın: internet var? Bot silinməyib? Ayarlar → Telegram → <strong>Sınaq mesajı</strong>.</p></div><p>Telegram-dakı backup-ı necə bərpa etmək: <a href="./backup.html#fayldan-berpa">Backup və bərpa</a>.</p>',10)])])}const k=e(l,[["render",i]]);export{p as __pageData,k as default};
